Current prototype:
```tsx
import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Alert,
  Modal,
  KeyBar,
} from '@nexti/ds';

type Errors = Partial<Record<'ORDEN' | 'EMPRESA' | 'TIPCTA' | 'CUENTA' | 'VALOR' | 'CANAL' | 'CLAVE', string>>;
type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

const digits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max);

// VALOR: 9(9)V99 -> up to 9 integer digits and 2 decimals
const money = (v: string) => {
  const clean = v.replace(',', '.').replace(/[^\d.]/g, '');
  const [int = '', ...rest] = clean.split('.');
  const dec = rest.join('').slice(0, 2);
  const i = int.slice(0, 9);
  return rest.length > 0 ? `${i}.${dec}` : i;
};

export default function PagoOrdenes({ navigate }: { navigate: (to: string) => void }) {
  const [orden, setOrden] = useState('');
  const [empresa, setEmpresa] = useState('');
  const [servic, setServic] = useState('');
  const [tipcta, setTipcta] = useState('');
  const [cuenta, setCuenta] = useState('');
  const [valor, setValor] = useState('');
  const [canal, setCanal] = useState('WEB');
  const [clave, setClave] = useState(''); // real value; shown masked (legacy "dark" attribute)
  const [errors, setErrors] = useState<Errors>({});
  const [mensaje, setMensaje] = useState<Msg>(null);
  const [confirmOpen, setConfirmOpen] = useState(false);

  // The "dark" field is never displayed: we keep the real text and show only bullets.
  const onClave = (v: string) => {
    if (v.length <= clave.length) {
      setClave(clave.slice(0, v.length));
    } else {
      const added = v.slice(clave.length).replace(/•/g, '');
      setClave((clave + added).slice(0, 6));
    }
  };

  // Prototype validations (the spec defines required fields, formats and lengths).
  const validate = (): Errors => {
    const e: Errors = {};
    if (!orden) e.ORDEN = 'El número de orden es obligatorio';
    if (!empresa) e.EMPRESA = 'La empresa es obligatoria';
    if (tipcta && tipcta.length !== 3) e.TIPCTA = 'El tipo de cuenta debe tener 3 caracteres';
    if (valor && !/^\d{1,9}(\.\d{1,2})?$/.test(valor)) e.VALOR = 'Valor inválido (hasta 9 enteros y 2 decimales)';
    if (canal !== 'WEB' && canal !== 'OFI') e.CANAL = 'El canal debe ser WEB u OFI';
    if (clave && clave.length !== 6) e.CLAVE = 'La clave de aprobación debe tener 6 caracteres';
    return e;
  };

  const pagar = () => {
    const e = validate();
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setMensaje({ tone: 'error', text: 'Revise los campos marcados antes de continuar.' });
      return;
    }
    setMensaje({ tone: 'success', text: 'Datos válidos. Confirme el pago para enviarlo.' });
    setConfirmOpen(true);
  };

  const cancelar = () => {
    setOrden('');
    setEmpresa('');
    setServic('');
    setTipcta('');
    setCuenta('');
    setValor('');
    setCanal('WEB');
    setClave('');
    setErrors({});
    setConfirmOpen(false);
    setMensaje({ tone: 'info', text: 'Operación cancelada. Se limpió el formulario.' });
  };

  const volver = () => navigate('SCR-PAGOMEN');

  return (
    <Screen
      title="Pago de órdenes"
      code="PAGOORD"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Pagar', onPress: pagar, primary: true },
            { key: 'PF3', label: 'Volver', onPress: volver },
            { key: 'PF12', label: 'Cancelar', onPress: cancelar },
          ]}
        />
      }
    >
      <Stack>
        <Card title="Datos del pago">
          <Stack>
            <Alert tone="info">Los campos con * son obligatorios.</Alert>

            <Grid columns={2}>
              <div data-field="ORDEN">
                <TextField
                  label="Número de orden"
                  required
                  numeric
                  maxLength={7}
                  hint="Hasta 7 dígitos"
                  error={errors.ORDEN}
                  value={orden}
                  onChange={(v: string) => setOrden(digits(v, 7))}
                />
              </div>

              <div data-field="EMPRESA">
                <TextField
                  label="Empresa"
                  required
                  numeric
                  maxLength={5}
                  hint="Hasta 5 dígitos"
                  error={errors.EMPRESA}
                  value={empresa}
                  onChange={(v: string) => setEmpresa(digits(v, 5))}
                />
              </div>

              <div data-field="SERVIC">
                <TextField
                  label="Servicio"
                  maxLength={10}
                  hint="Hasta 10 caracteres"
                  value={servic}
                  onChange={(v: string) => setServic(v.toUpperCase().slice(0, 10))}
                />
              </div>

              <div data-field="TIPCTA">
                <TextField
                  label="Tipo de cuenta"
                  maxLength={3}
                  hint="3 caracteres"
                  error={errors.TIPCTA}
                  value={tipcta}
                  onChange={(v: string) => setTipcta(v.toUpperCase().slice(0, 3))}
                />
              </div>

              <div data-field="CUENTA">
                <TextField
                  label="Cuenta"
                  numeric
                  maxLength={10}
                  hint="Hasta 10 dígitos"
                  value={cuenta}
                  onChange={(v: string) => setCuenta(digits(v, 10))}
                />
              </div>

              <div data-field="VALOR">
                <TextField
                  label="Valor"
                  numeric
                  maxLength={12}
                  hint="Hasta 9 enteros y 2 decimales. Ej.: 125000.50"
                  error={errors.VALOR}
                  value={valor}
                  onChange={(v: string) => setValor(money(v))}
                />
              </div>

              <div data-field="CANAL">
                <SelectField
                  label="Canal (WEB/OFI)"
                  options={[
                    { value: 'WEB', label: 'WEB' },
                    { value: 'OFI', label: 'OFI' },
                  ]}
                  error={errors.CANAL}
                  value={canal}
                  onChange={(v: string) => setCanal(v)}
                />
              </div>

              <div data-field="CLAVE">
                <TextField
                  label="Clave de aprobación"
                  maxLength={6}
                  hint="6 caracteres. Se oculta al digitar"
                  error={errors.CLAVE}
                  value={'•'.repeat(clave.length)}
                  onChange={onClave}
                />
              </div>
            </Grid>
          </Stack>
        </Card>

        <div data-field="MENSAJE" aria-live="polite">
          {mensaje ? (
            <Alert tone={mensaje.tone}>{mensaje.text}</Alert>
          ) : (
            <span style={{ opacity: 0.6 }}>Sin mensajes.</span>
          )}
        </div>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={pagar}>
            Pagar
          </Button>
          <Button variant="secondary" shortcut="PF3" onClick={volver}>
            Volver
          </Button>
          <Button variant="danger" shortcut="PF12" onClick={cancelar}>
            Cancelar
          </Button>
        </Row>
      </Stack>

      <Modal title="Confirmar pago" open={confirmOpen} onClose={() => setConfirmOpen(false)}>
        <Stack>
          <p>
            Se pagará la orden <strong>{orden}</strong> de la empresa <strong>{empresa}</strong>
            {valor ? (
              <>
                {' '}por un valor de <strong>{valor}</strong>
              </>
            ) : null}{' '}
            por el canal <strong>{canal}</strong>.
          </p>
