const money = (v: string) => {
  const clean = v.replace(',', '.').replace(/[^\d.]/g, '');
  const [int = '', ...rest] = clean.split('.');
  const dec = rest.join('').slice(0, 2);
  const i = int.slice(0, 9);
  return rest.length > 0 ? `${i}.${dec}` : i;
};

