              />
            </div>

            <div data-field="CUENTA">
              <TextField
                label="Cuenta"
                numeric
                maxLength={10}
                hint="Hasta 10 dígitos"
                value={cuenta}
                onChange={(v: string) => setCuenta(digits(v, 10))}
              />
            </div>

            <div data-field="VALOR" className="pagoord-valor">
              <TextField
                label="Valor"
                numeric
                maxLength={12}
                hint="Hasta 9 enteros y 2 decimales. Ej.: 125000.50"
                error={errors.VALOR}
                value={valor}
                onChange={(v: string) => setValor(money(v))}
              />
            </div>
          </Grid>
        </Card>

        <Card title="Canal y aprobación">
          <Grid columns={2}>
            <div data-field="CANAL">
              <SelectField
                label="Canal (WEB/OFI)"
                options={[
